WPM=155
DATA={
 "latency":{"labels":["On-premise (RTX 4090)","AWS (L4)"],"stages":["upload","wait before GPU","GPU side"],"values":[[0.007,16.1,111.5],[3.3,19.4,392.3]]},  # report s4: warm 30 s clip, end to end 127.6 s / 415 s
 "scaling":{"labels":["job 1","job 2","job 3","job 4","job 5"],"aws":[853,1176,1499,1822,2145],"onprem":[None,None,None,None,575]},  # report s4: five uploads at once, finish time (s)
 "sus":{"score":None,"success":None},                         # SUS 0-100, tasks completed of 5
 "breakeven":{"fixed":5,"perVideo":0.23,"onprem":159},        # report s3: $/month and $/video (AWS), $/month (RTX 4090 rig)
}
def R(d,t,cls=""): return f"<div class='reveal {cls}' style='--d:{d}'>{t}</div>"
S=[]
SECT={'P1':'Business Need','P2':'Business Model','P3':'Demo','P4':'Evaluation','P5':'Conclusion'}
def add(p,label,body,script,kind="std"): S.append((p,label,body,script,kind))
def pad(inner,cls=""): return f"<div class='pad {cls}'>{inner}</div>"
def shot(img,l,t,w,cap=None):
    h=round(w*844/1440); c=f"<div class='cap' style='left:{l}px;top:{t+h+16}px'>{cap}</div>" if cap else ""
    return f"<div class='reveal shot' style='left:{l}px;top:{t}px;width:{w}px;--d:1'><img src='img/{img}.png' alt=''></div>{c}"
def cues(items): return "<ul class='cues reveal' style='--d:2'>"+''.join(f"<li><b>{k+1}</b>{x}</li>" for k,x in enumerate(items))+"</ul>"
def dtitle(t): return f"<div class='reveal' style='position:absolute;left:140px;top:104px;font-size:64px;font-weight:600;letter-spacing:-.03em;--d:0;display:flex;align-items:center;gap:28px'><span class='live mono' style='font-size:24px'>LIVE</span><span>{t}</span></div>"
CURVE="<svg class='curve' viewBox='0 0 1920 220' preserveAspectRatio='none'><line x1='0' y1='150' x2='1920' y2='150' stroke='#262A31' stroke-width='2' stroke-dasharray='8 12'/><path class='draw' pathLength='1' stroke='#FF8A2A' stroke-width='5' d='M0 120 C160 110 240 140 360 96 S600 30 740 40 S1020 70 1180 56 S1500 30 1620 92 S1800 150 1920 200'/></svg>"

# ---------------- P1 ----------------

def A(d,l,t,inner,w=None):
    ww=f"width:{w}px;" if w else ""
    return f"<div class='reveal' style='position:absolute;left:{l}px;top:{t}px;{ww}--d:{d}'>{inner}</div>"
FF="font-family='Space Grotesk,sans-serif'"
def tribe_svg():
    s="<svg viewBox='0 0 1640 500' width='1640' height='500'><defs><marker id='a1' viewBox='0 0 10 10' refX='8' refY='5' markerWidth='9' markerHeight='9' orient='auto'><path d='M0 0L10 5L0 10z' fill='#FF8A2A'/></marker></defs>"
    for y,a,b in [(20,'Frames','V-JEPA 2 watches'),(190,'Sound','Wav2Vec-BERT listens'),(360,'Words','WhisperX + LLaMA 3.2 read')]:
        s+=f"<rect x='0' y='{y}' width='480' height='120' rx='18' fill='#14171C' stroke='#262A31' stroke-width='2'/><text x='34' y='{y+54}' {FF} font-size='42' font-weight='600' fill='#E8EAED'>{a}</text><text x='34' y='{y+96}' {FF} font-size='28' fill='#8B929C'>{b}</text>"
        s+=f"<path d='M480 {y+60} C 570 {y+60} 540 250 644 250' fill='none' stroke='#FF8A2A' stroke-width='3' marker-end='url(#a1)'/>"
    s+=f"<rect x='650' y='110' width='380' height='280' rx='26' fill='#1b140d' stroke='#FF8A2A' stroke-width='3'/><text x='840' y='235' text-anchor='middle' {FF} font-size='62' font-weight='600' fill='#E8EAED'>TRIBE v2</text><text x='840' y='292' text-anchor='middle' {FF} font-size='28' fill='#8B929C'>1,000+ hours of fMRI</text><text x='840' y='332' text-anchor='middle' {FF} font-size='28' fill='#8B929C'>from 720 people</text>"
    s+="<path d='M1030 250 L1196 250' stroke='#FF8A2A' stroke-width='3' marker-end='url(#a1)'/><image href='img/brain.png' x='1210' y='50' width='380' height='380'/>"
    s+=f"<text x='1400' y='478' text-anchor='middle' {FF} font-size='28' fill='#8B929C'>20,484 cortex points, every second</text></svg>"
    return s
def bm_body():
    dots="".join("<i style='display:inline-block;width:44px;height:44px;border-radius:50%;background:#FF8A2A;margin-right:14px'></i>" for _ in range(10))
    left=A(1,140,300,"<div class='big' style='font-size:230px'>$1.00</div><p class='sub' style='font-size:40px;margin-top:20px'>per started 30 s of video</p><div style='margin-top:60px'>"+dots+"</div><p class='mono' style='margin-top:22px'>New users: $10 credit = ten 30 s videos</p>",800)
    def row(label,w,pct): return f"<p style='font-size:32px;color:var(--muted);margin-top:46px'>{label}</p><div style='display:flex;align-items:center;gap:22px;margin-top:14px'><div style='height:64px;width:{w}px;background:#FF8A2A;border-radius:6px'></div><span style='font-size:52px;font-weight:600'>{pct}</span></div>"
    right=A(2,1000,310,"<p class='mono hl'>Why prepaid credit: card fee as a share of the charge</p>"+row("A $1.00 video, paid by card",520,"≈ 33%")+row("A $20 credit pack",70,"≈ 4%"),780)
    foot=A(3,140,950,"<p class='mono'>Course version: an administrator grants credit · Stripe Checkout belongs to the production design</p>",1640)
    return left+right+foot
def econ_body():
    def row(label,w,val,c,extra): return f"<div style='display:grid;grid-template-columns:520px 1fr;align-items:center;margin-bottom:50px'><span style='font-size:34px;color:var(--muted)'>{label}</span><div style='display:flex;align-items:center;gap:24px'><div style='height:76px;width:{w}px;background:{c};border-radius:6px'></div><span style='font-size:50px;font-weight:600'>{val}</span><span style='font-size:34px;color:#FFC24A'>{extra}</span></div></div>"
    rows=row("Price per 30 s video",900,"$1.00","#FF8A2A","")+row("Our cost, 3 videos a session",207,"$0.23","#8B929C","77% margin")+row("Our cost, 30 videos a session",126,"$0.14","#8B929C","86% margin")
    return A(1,140,340,rows,1640)+A(2,140,900,"<p class='mono'>GPU 393 s at $1.22/h (L4) · start-up and idle shared across a session · fixed cost $5 a month</p>",1640)
def gpu_chart_svg():
    s="<svg viewBox='0 0 960 520' width='960' height='520'>"
    s+=f"<text x='0' y='28' {FF} font-size='26' fill='#8B929C'>Time to analyse one clip</text><rect x='560' y='8' width='22' height='22' fill='#FF8A2A'/><text x='592' y='28' {FF} font-size='26' fill='#E8EAED'>L40S</text><rect x='690' y='8' width='22' height='22' fill='#8B929C'/><text x='722' y='28' {FF} font-size='26' fill='#E8EAED'>L4</text>"
    s+="<line x1='0' y1='450' x2='960' y2='450' stroke='#262A31' stroke-width='2'/>"
    for cx,lab,a,b in [(250,'52 s clip',259,655),(700,'119 s clip',491,1540)]:
        for x,v,c in [(cx-140,a,'#FF8A2A'),(cx+10,b,'#8B929C')]:
            h=v/1540*340
            s+=f"<rect x='{x}' y='{450-h:.0f}' width='130' height='{h:.0f}' fill='{c}'/><text x='{x+65}' y='{450-h-12:.0f}' text-anchor='middle' {FF} font-size='30' fill='#E8EAED'>{v:,} s</text>"
        s+=f"<text x='{cx}' y='496' text-anchor='middle' {FF} font-size='28' fill='#8B929C'>{lab}</text>"
    return s+"</svg>"
def val_body():
    def col(l,kicker,big,cap,big2=None,cap2=None):
        extra=f"<div class='big' style='font-size:100px;margin-top:40px'>{big2}</div><p style='font-size:28px;color:var(--muted);margin-top:8px'>{cap2}</p>" if big2 else ""
        return f"<p class='mono hl'>{kicker}</p><div class='big' style='font-size:130px;margin-top:20px'>{big}</div><p style='font-size:28px;color:var(--muted);margin-top:8px'>{cap}</p>{extra}"
    cols="<div style='display:grid;grid-template-columns:repeat(3,1fr);gap:70px'>"+f"<div>{col(0,'The model: validated by Meta','720','people scanned; accurate on new videos, tasks and people. Not re-tested by us.')}</div>"+f"<div>{col(0,'Our pipeline','0.005','largest difference, RTX 4090 vs AWS, across 11 series','77/80','refund tests passed')}</div>"+f"<div>{col(0,'Our users','[TBD]','SUS score and survey: see Usability')}</div></div>"
    return A(1,140,330,cols,1640)+A(2,140,900,"<p class='sub' style='font-size:34px;margin-top:0'>Not validated: that a higher response means <span class='hl'>more views or sales</span>.</p>",1640)


add("P1","",pad("<div class='fill'>"+R(0,"<h1>NeuroLens</h1>")+R(1,"<div class='tag hl' style='font-size:64px'>Watch a brain watch your video.</div>")+R(2,"<p class='mono' style='margin-top:48px'>Predicted brain response to video, second by second</p>")+R(3,"<p class='mono' style='margin-top:14px'>CS5224 Cloud Computing · Final presentation · Dylan Chan · Xin Wei Chong · Kelvin Low · Joshua Lum · Brandon Tan</p>")+"</div>","title")+CURVE,
"Good afternoon, everyone. We're team NeuroLens, and we'll show you a cloud service that predicts how a viewer's brain responds to a video, second by second, without putting anyone in a scanner. I'll cover the business need and the brain model behind it. Then we'll cover the business model, a live demo, how we evaluated it, and the ethics and next steps.","title")
add("P1","Problem",pad("<div class='fill'><div style='display:grid;grid-template-columns:660px 1fr;gap:70px;align-items:center'>"+R(0,"<div class='big' style='font-size:250px'>$10k+</div><p class='sub' style='margin-top:30px;font-size:40px'>to test one ad on a brain scanner</p>")+R(1,"<div class='rows'><div class='r'><span>fMRI study</span><span>$10 – 15k</span><span>2–4 weeks</span></div><div class='r us'><span>NeuroLens</span><span>$1.00</span><span>≈ 7 min</span></div></div>")+"</div>"+"</div>"),
"Let's start with a simple question: how do you know whether an ad works? Surveys are the usual answer, but people are bad at explaining their own reactions. Brain scans do better, because they show how viewers really react, second by second. The catch is the price. An fMRI study costs ten to fifteen thousand dollars per advert and takes two to four weeks. NeuroLens costs one dollar for a thirty-second video and takes about seven minutes, which we measured. That gap is the reason this project exists.")
add("P1","Why now",pad("<div style='display:grid;grid-template-columns:960px 1fr;gap:40px;flex:1;align-items:center'><div>"+R(0,"<h1 style='font-size:80px'>Ten cuts by lunch.<br><em>No way to judge them.</em></h1>")+R(1,"<p class='sub'>Generative tools made production cheap. The feed made every second count.</p>")+"</div>"+R(2,"<svg viewBox='0 0 800 520' width='800' height='520'><line x1='0' y1='290' x2='800' y2='290' stroke='#262A31' stroke-width='2' stroke-dasharray='8 12'/><path class='draw' pathLength='1' stroke='#FF8A2A' stroke-width='6' d='M0 120 C100 110 170 100 250 140 S340 170 390 290 S480 450 540 420 S650 300 720 350 S780 400 800 450'/><circle cx='505' cy='430' r='26' fill='none' stroke='#FFC24A' stroke-width='4'/><text x='440' y='500' fill='#FFC24A' font-family='JetBrains Mono' font-size='26'>where did we lose them?</text><text x='0' y='40' fill='#8B929C' font-family='JetBrains Mono' font-size='24'>VIEWER ATTENTION (ILLUSTRATIVE)</text></svg>")+"</div>"),
"And the gap is getting wider. Generative tools mean a small team can now produce ten versions of an ad before lunch, and every version has to be judged. Viewers watch in fast-scrolling feeds, where one swipe ends the ad, so you can lose someone at a quiet stretch, like this dip. Creators ask: where exactly did I lose them, and which version is stronger?")
add("P1","Industry",pad("<div class='fill'>"+R(0,"<h1>What already exists: <em>measured, filmed or guessed.</em></h1>")+R(1,"<div class='rows' style='margin-top:20px'><div class='r' style='grid-template-columns:600px 400px 1fr;font-size:32px;padding:12px 0'><span>Brain scans (fMRI, EEG)<br><small style='font-size:24px;color:var(--muted);font-weight:400'>research labs, iMotions suites</small></span><span>$10,000 – $15,000</span><span>2–4 weeks</span></div><div class='r' style='grid-template-columns:600px 400px 1fr;font-size:32px;padding:12px 0'><span>Facial coding<br><small style='font-size:24px;color:var(--muted);font-weight:400'>Realeyes, iMotions webcam studies</small></span><span>$850 – $4,000</span><span>3–5 days</span></div><div class='r' style='grid-template-columns:600px 400px 1fr;font-size:32px;padding:12px 0'><span>AI attention maps<br><small style='font-size:24px;color:var(--muted);font-weight:400'>Neurons AI, Attention Insight</small></span><span>$500 – $1,500 / mo</span><span>sub-minute</span></div><div class='r us' style='grid-template-columns:600px 400px 1fr;font-size:32px;padding:12px 0'><span>NeuroLens<br><small style='font-size:24px;color:var(--muted);font-weight:400'>predicted brain response</small></span><span>$1.00</span><span>≈ 7 min</span></div></div>")+"<div class='cols c3' style='gap:60px;margin-top:24px'>"+R(2,"<p class='mono hl'>Our difference</p><h2 style='font-size:38px'>A brain response, not a gaze or a face</h2>")+R(3,"<p class='mono hl'>&nbsp;</p><h2 style='font-size:38px'>Per second, with a no-sound pass</h2>")+R(4,"<p class='mono hl'>&nbsp;</p><h2 style='font-size:38px'>Compare any two cuts for $1.00</h2>")+"</div>"+"</div>"),
"So what already exists? Three groups. First, lab studies: brain scans or EEG, run by research teams or suites like iMotions. They measure real brains, but cost a fortune and take weeks. Second, facial coding, from vendors like Realeyes, which reads viewers' faces. It is cheaper, but it reads faces, not brains. Third, AI attention tools such as Neurons AI and Attention Insight, which predict from the creative itself where eyes will land. They are fast, but they show what is noticed, not how a brain responds. NeuroLens sits in the gap: a predicted brain response for every second, with a second pass that removes the sound, for a dollar.")
add("P1","TRIBE v2",pad(R(0,"<h1>Under the hood: <em>TRIBE v2.</em></h1>"))+A(1,140,330,tribe_svg()),
"The model underneath is TRIBE v2, from Meta's AI research lab. It was trained on over a thousand hours of real fMRI from 720 people. It takes three inputs, frames, sound and words, through four models: V-JEPA 2 watches, Wav2Vec-BERT listens, and WhisperX and LLaMA 3.2 handle the speech. Out comes predicted activity at twenty thousand four hundred and eighty-four points on the cortex, every second. In Meta's paper it handles new videos and new people several times better than older models.")
add("P1","Signals",pad(R(0,"<h1>Seven signals, <em>three questions.</em></h1>"))+A(1,140,330,"<img src='img/signals.png' alt='' style='width:1640px;display:block;border:1px solid var(--line);border-radius:4px'>")+A(2,147,770,"<p class='mono hl'>Seeing</p><p style='font-size:34px;margin-top:8px'>faces · bodies · scenes · visual</p>",520)+A(2,704,770,"<p class='mono hl'>Hearing</p><p style='font-size:34px;margin-top:8px'>sound</p>",520)+A(2,1261,770,"<p class='mono hl'>Understanding</p><p style='font-size:34px;margin-top:8px'>speech · social</p>",520)+A(3,140,900,"<div style='height:10px;border-radius:5px;background:linear-gradient(90deg,#2a3a55,#2a2f38 45%,#6b3a12 60%,#FF8A2A 80%,#FFC24A)'></div><div style='display:flex;justify-content:space-between;margin-top:12px' class='mono'><span>below typical</span><span>0 = typical film &amp; TV viewing</span><span>above typical</span></div>",1640),
"We turn those cortex points into seven signals in three groups, using brain areas from the Glasser atlas. Seeing covers faces, bodies, scenes and visual areas. Hearing covers sound. Understanding covers speech and social cues. This is a crop of our live site. The scale is the same on all three, and zero means typical film and TV viewing, so any two videos compare directly. A second pass with the sound removed shows what the soundtrack adds. Hold on to these three groups, because you'll see them move in the demo. Over to my teammate for the business model.")
add("P2","Business model",pad(R(0,"<h1>Pay as you go. <em>Credit, not cards.</em></h1>"))+bm_body(),
"Thanks. NeuroLens is for independent creators and small agencies who make many AI-generated versions of an advert and need to pick one before paying for media. It's pay as you go: one dollar for each started thirty seconds, from prepaid credit. New users get ten dollars, enough for ten videos. Why credit, not a card per video? A card fee of about 2.9 percent plus thirty cents takes about a third of a one-dollar charge, but only about four percent of a twenty-dollar pack. In our proof of concept an administrator grants the credit, and Stripe belongs to the production design. One caveat: TRIBE v2 is non-commercial, so a paid launch needs a licence.")
add("P2","Unit economics",pad(R(0,"<h1>What one analysis <em>costs us.</em></h1>"))+econ_body(),
"What does one analysis cost us? About 393 seconds of GPU time on an L4 at one dollar twenty-two an hour: thirteen cents. Each session also pays for one GPU start-up and seven idle minutes, shared across its videos. With three videos in a session, a video costs us twenty-three cents. With thirty, fourteen cents. Against a one-dollar price, that is a gross margin of seventy-seven to eighty-six percent, plus about five dollars a month fixed. We hoped for ten cents on Spot GPUs, but Spot capacity was not available.","data")
add("P2","SaaS vs on-premise",pad(R(0,"<h1>Cloud is cheaper below about <em>670 videos a month.</em></h1>")+"<div class='chart reveal fill' data-viz='break' style='--d:1'><div class='vz'></div></div>"),
"Why cloud rather than buying a GPU? We priced a machine with one RTX 4090 at five thousand dollars, with a three-year life. The model peaked at 19.9 gigabytes, so a 24 gigabyte card is enough. With idle power, that is about one hundred fifty-nine dollars a month, flat, and almost nothing per video, about a third of a cent of electricity. AWS has no hardware cost and about five dollars a month fixed, but twenty-three cents a video. The lines cross at 670 videos a month. Below that, renting by the hour is cheaper, and ad testing comes in bursts: thirty versions one week, none the next month. Above it, owning wins: at a thousand videos a month over three years, that is about fifty-eight hundred dollars owned against eighty-five hundred on AWS. The price of renting is a wait, which you'll see in the demo and our results. Over to my colleague, who'll show it live.","data")
add("P3","Demo",dtitle("Live demo: sign in, upload, explore")+"<div class='reveal shot' style='left:140px;top:220px;width:1290px;--d:1'><a href='https://df6girqyykyfa.cloudfront.net' target='_blank' rel='noopener'><img src='img/result.png' alt='NeuroLens result page'></a></div><div class='cap' style='left:140px;top:992px'>Click the picture to open the live site · df6girqyykyfa.cloudfront.net</div>"+cues(["Upload: price first","Peak, dip, no-sound toggle","Seeing · hearing · understanding","AI report, compare, bad file"]),
"Thanks. Now let me show you the real thing. This is the live site, running on AWS, and the picture on the slide is a link to it. I'll sign in with Google; email and password works too. Up here is my credit balance, and below it the upload area. I'll pick a thirty-second clip. Before anything is sent, the app tells me exactly what it will cost: one dollar for each started thirty seconds. I get a short window to cancel, because GPU time costs real money, and then I confirm. The file goes straight from my browser to cloud storage, and the job moves through stages I can watch: checking the file, waiting for a GPU, and analysing. We warmed a GPU up before this session, but even warm, a thirty-second clip takes about seven minutes, so I'll leave it running and open a finished sample: the thirty-second CeraVe ad, one of our free samples. On the left, the video plays with a 3D brain synced to it, and you can drag the brain to rotate it. Everything on the right follows the playhead. The orange line is the overall predicted response of an average viewer, compared with typical viewing. Around second six, when the actor holds up the product and looks at the camera, it peaks, and the label says well above typical. The orange dots mark moments the system flags as notable, and the strip of frames underneath shows what was on screen at each point. Now the three groups we just met. Seeing, hearing and understanding sit on the same scale, so you can see which one drives the peak. Here it is seeing and hearing together, the face and the voice, and you can open each group to see its parts. Towards the end the line falls below typical, on the closing product card, with no face and no speech. The toggle shows the same video without sound. That is the second pass I described, and the page tells us forty-six percent of the response comes from the soundtrack. Numbers are useful, but creators want advice. The Report tab is written by an AI model that reads the brain data and the video frames together. It lists strengths and improvements, then specific moments, with the second each one starts, what is on screen, and what the brain is doing. The Compare tab puts two videos side by side: here, the thirty-second cut against the longer cut of the same ad. The verdict says the short cut's direct opening gives it an early edge, but the two finish close. You can also download the results. One last thing people ask: what if someone uploads something that is not a video? I'll try a text file renamed to MP4. It is rejected within seconds, before any GPU starts, and nothing is charged. Failed jobs are refunded automatically too. Over to my colleague, who will show how we evaluated it.","demo")
add("P4","Validation",pad(R(0,"<h1>How do we know <em>it works?</em></h1>"))+val_body(),
"Thanks. Now evaluation, starting with a simple question: how do we know it works? There are three layers. The model: its accuracy on new videos, new tasks and new people was shown by Meta's team in the TRIBE v2 paper. We did not repeat that against real scans, and we did not test whether the predictions relate to views, retention or sales, so we make no such claim. Our pipeline: we ran the same code and the same clip on our own RTX 4090 and on AWS, and across all eleven series, with and without sound, no value differs by more than 0.005. For billing, 77 of 80 automated refund tests refunded a failed job exactly once; the other three stopped on a GPU-library error during setup, and we did not kill a job on the live site. About 1,200 automated tests cover the code. Our users: the usability results come last.","data")
add("P4","Latency",pad(R(0,"<h1>Where does the time <em>go in one job?</em></h1>")+R(1,"<p class='sub' style='margin-top:14px;font-size:32px'>Same code, same 30 s clip, on our own RTX 4090 and on AWS.</p>")+"<div class='chart reveal fill' data-viz='latency' style='--d:2'><div class='vz'></div><div class='lg'></div></div>"+R(3,"<p class='mono'>GPU time per video-second: 3.71 s (RTX 4090) vs 10.7 s (A10G) · first video after 7+ min idle: 779 s on AWS</p>")),
"Next, speed. We ran the same code and the same thirty-second clip on a machine we own and on AWS. The GPUs differ, so GPU work is compared per second of video: 3.7 seconds on the RTX 4090, against 10.7 on an A10G on AWS. End to end, a warm thirty-second clip takes 128 seconds on our machine and 415 on AWS. Upload takes about three seconds, the wait before the GPU starts about nineteen, and the rest is the model. After a long idle, the first video takes about 779 seconds, because a GPU has to start.","data")
add("P4","Scaling",pad(R(0,"<h1>Five people <em>at once.</em></h1>")+R(1,"<p class='sub' style='margin-top:14px;font-size:32px'>Five uploads at once. The endpoint is set to one GPU, so jobs run one after another.</p>")+"<div class='chart reveal fill' data-viz='scaling' style='--d:2'><div class='vz'></div><div class='lg'><span><i style='background:#FF8A2A'></i>AWS, finish time of each job</span><span><i style='background:#8B929C'></i>On-premise, last job</span></div></div>"+R(3,"<p class='mono'>Seconds until each job finishes. No job was dropped. The AWS run got an A10G, and its first job appears to have restarted once.</p>")),
"Next, load. What happens when several people upload at once? We sent five uploads at the same time. Both setups run one job at a time, so the jobs queue. On AWS they finished about 323 seconds apart, the last after 2,145 seconds. On our machine the last finished after 575. Nothing was dropped. Serving more people at once would need a GPU quota increase.","data")
add("P4","Usability",pad("<div style='display:grid;grid-template-columns:1fr 1fr;gap:100px;flex:1;align-items:center' data-viz='sus'><div>"+R(0,"<h1>Can people <em>use it?</em></h1>")+R(1,"<p class='sub'>Booth visitors tried a sample or uploaded a clip, then answered the 10-question SUS.</p>")+"</div>"+R(2,"<div class='stat'><span class='sc'>[TBD]</span><small> / 100</small></div><p class='mono' style='margin-top:10px'>SUS score · 68 is average · 80 is very good</p><p class='mono' style='margin-top:40px'>[x]% saw something they had not noticed</p><p class='mono'>[y]% would pay $1.00 for a 30 s video</p>")+"</div>"),
"Last, usability. At our booth, [N] visitors tried NeuroLens, a small formative test, and answered the System Usability Scale. The average product scores sixty-eight, and eighty is usually read as very good. Our mean score was [TBD], with a range of [TBD]. [x] percent said it showed them something they had not noticed, and [y] percent would pay one dollar to analyse a thirty-second video. One person said: [TBD quote]. The biggest issue raised was [TBD]. Now my colleague will cover ethics and where this goes next.","data")
add("P5","Limits and ethics",pad(R(0,"<h1>What it claims, <em>and what it doesn't.</em></h1>")+"<div class='cols c3' style='margin-top:90px;gap:60px'>"+R(1,"<p class='mono hl' style='margin-bottom:18px'>What it is</p><ul class='list'><li>An average viewer's brain response</li><li>One scale for every video</li></ul>")+R(2,"<p class='mono' style='margin-bottom:18px'>What it isn't</p><ul class='list no'><li>A prediction of views or sales</li><li>Instant: first video ≈ 6 min</li></ul>")+R(3,"<p class='mono hl' style='margin-bottom:18px'>Ethics</p><ul class='list'><li>Non-commercial licence (CC BY-NC)</li><li>No one scanned or profiled</li><li>Anonymous, consented survey</li></ul>")+"</div>"),
"Thanks. Ethics and limits. What it is: an average viewer's predicted brain response, second by second, on one scale for every video, a virtual pre-test for editing. What it isn't: a prediction of views or sales, which we did not test. It isn't instant, since the first video after a quiet spell waits about six minutes for a GPU. And our usability study was small, enough to find the main problems but not to make statistical claims. On ethics: TRIBE v2 is non-commercial, so a paid launch needs a licence from Meta or a different model. No real person is scanned or profiled, because the model predicts an average viewer from the video alone. Still, a tool that shows what holds attention could be used to hold it at any cost, so we position it for checking edits, not for manipulating individuals. Our booth survey was anonymous and asked for consent first, and our report declares how we used AI tools.")
add("P5","Where next",pad(R(0,"<h1>Where next: <em>scaling up.</em></h1>"))+A(1,140,290,gpu_chart_svg())+A(2,1180,300,"<div class='big' style='font-size:130px'>26 / 26</div><p style='font-size:30px;color:var(--muted);margin-top:10px'>Spot launches failed for lack of capacity</p><div class='big' style='font-size:130px;margin-top:50px'>19.9 GB</div><p style='font-size:30px;color:var(--muted);margin-top:10px'>peak GPU memory: a 24 GB card fits</p>",600)+A(3,140,850,"<p class='sub' style='font-size:32px;margin-top:0'>An EC2 GPU pool: <span class='hl'>$0.10 – $0.20</span> a video, about $70 more a month. It pays off above about 1,000 videos a month. Estimates, not built.</p>",1640),
"Where does this go next? Our proof of concept runs one GPU at a time. The preliminary report described a larger design: containers behind a load balancer and a pool of EC2 GPU workers that scales with the queue. We built part of it, then moved the GPU to SageMaker after three findings. Spot did not deliver: all twenty-six launches failed for lack of capacity, and Spot was only one to nine percent cheaper. A smaller GPU is enough, since the model peaked at about twenty gigabytes. And the GPU sets the speed: an L40S finished a 119 second clip in 491 seconds, against 1,540 on an L4. The larger design adds about seventy dollars a month of fixed cost, so it only pays off above roughly a thousand videos a month. At today's volume SageMaker is the better choice, and the first step is to build it and measure its start-up time.","data")
add("P5","Conclusion",pad(R(0,"<h1>A $10,000 brain study,<br><em>in 7 minutes for $1.</em></h1>"))+A(1,140,470,"<div style='display:grid;grid-template-columns:repeat(4,1fr);gap:40px'>"+"".join(f"<div><div class='big' style='font-size:96px'>{a}</div><p style='font-size:28px;color:var(--muted);margin-top:12px'>{b}</p></div>" for a,b in [("$1.00","per 30 s video"),("≈ 7 min","to a result, GPU warm"),("670","videos a month: break-even vs owning"),("≈ 6 min","first video after a quiet spell")])+"</div>",1640)+"<div class='flow reveal' style='grid-template-columns:repeat(3,1fr);position:absolute;left:140px;top:760px;width:1640px;--d:3'><div class='n'><i>Next</i><b>Licence</b><span>CC BY-NC: a paid launch needs one.</span></div><div class='n'><i>Next</i><b>Scale</b><span>A GPU pool that grows with the queue.</span></div><div class='n'><i>Next</i><b>Polish</b><span>Fix what our usability study flagged.</span></div></div>",
"To wrap up. NeuroLens predicts a viewer's brain response to a video and returns it in about seven minutes for about one dollar, where an fMRI study costs ten thousand dollars or more and takes weeks. Below 670 videos a month, renting a GPU costs less than owning one. The trade-off is the wait: after a quiet spell, the first video waits about six minutes. The model predicts an average viewer, not views or sales. Our next steps are a commercial licence, the scaled-up design once we have built and measured it, and fixing what our usability study found. Thank you for listening. We'd be happy to take your questions.")
add("P5","Q&amp;A",pad("<div class='fill'>"+R(0,"<h1>Thank you.<br><em>Questions?</em></h1>")+R(1,"<p class='hl2' style='font-size:60px;margin-top:70px;font-weight:500'>df6girqyykyfa.cloudfront.net</p>")+R(2,"<p class='mono' style='margin-top:18px'>Code · github.com/kelvinlowhm86/neurolens</p>")+"</div>"),
"Open for questions. Keep answers ready on: why this model and its licence, what the prediction does and does not mean, the cloud design and the cold-start wait, why SageMaker rather than Spot or our own GPU pool (production design slide), how refunds work, and what the experiments showed.","title")
# ---------------- build ----------------
esc=lambda x: html.escape(x,quote=True)
words=lambda s: len(re.findall(r"\S+",s))
N=len(S); out=[]; per={}
for i,(p,l,b,sc,k) in enumerate(S,1):
    w=words(sc); sec=round(w/WPM*60); per.setdefault(p,[0,0]); per[p][0]+=w; per[p][1]+=sec
    kick=f"<div class='kicker'>{i:02d} · {l}</div>" if l else ""
    out.append(f"<section class='slide {k}'>{kick}<div class='who'>{SECT.get(p,'')}</div>{b}<div class='pgn'>{i}/{N}</div><template><span class='m'>{p} · {w} words · ~{sec}s</span> {esc(sc)}</template></section>")
open('Slides.html','w').write(open('template.html').read().replace('%%SLIDES%%','\n'.join(out)).replace('%%DATA%%',json.dumps(DATA)))
md=["# NeuroLens: presentation script\n",f"Target: 450-500 words per presenter (~{WPM} words/min). Slides 1-19 are the talk, 20 is Q&A. `[TBD]` = fill from the usability study (edit DATA in gen.py for charts). Numbers come from the final report.\n"]
cur=None
for i,(p,l,b,sc,k) in enumerate(S,1):
    if p!=cur: md.append(f"\n## {p}{' · '+SECT[p] if p in SECT else ''}: {per[p][0]} words, ~{per[p][1]//60}:{per[p][1]%60:02d}\n"); cur=p
    md.append(f"**Slide {i}: {l or 'Title'}** ({words(sc)} words)\n\n> {sc}\n")
tw=sum(v[0] for k,v in per.items() if k!='ALL'); ts=sum(v[1] for k,v in per.items() if k!='ALL')
md.append(f"\n**Total: {tw} words, ~{ts//60}:{ts%60:02d}**\n"); open('Script.md','w').write('\n'.join(md))
for p,v in per.items(): print(p,v[0],'words',v[1],'s')
print('total',tw,ts//60,ts%60)
